package com.careerpilot.careerai;
import com.fasterxml.jackson.databind.*;import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.*;import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.test.context.ActiveProfiles;import org.springframework.test.web.servlet.MockMvc;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest(properties={"spring.datasource.url=jdbc:h2:mem:careerai;MODE=PostgreSQL;DB_CLOSE_DELAY=-1","spring.datasource.driver-class-name=org.h2.Driver","spring.datasource.username=sa","spring.datasource.password=","spring.jpa.hibernate.ddl-auto=create-drop","spring.flyway.enabled=false","careerpilot.ai.enabled=false"})@AutoConfigureMockMvc@ActiveProfiles("test")class CareerAiFlowIntegrationTest{@Autowired MockMvc mvc;@Autowired ObjectMapper json;
 @Test void requiresAuthenticationAndFailsExplicitlyWhenGeminiDisabled()throws Exception{mvc.perform(post("/api/v1/career-ai/copilot").contentType("application/json").content("{\"question\":\"What should I improve?\"}")).andExpect(status().isUnauthorized());String auth=register();complete(auth);mvc.perform(post("/api/v1/career-ai/copilot").header("Authorization",auth).contentType("application/json").content("{\"question\":\"What should I improve?\"}")).andExpect(status().isServiceUnavailable()).andExpect(jsonPath("$.message").value("AI coaching is temporarily unavailable"));mvc.perform(post("/api/v1/career-ai/interview").header("Authorization",auth).contentType("application/json").content("{\"targetCareer\":\"Backend Developer\",\"mode\":\"UNSUPPORTED\"}")).andExpect(status().isBadRequest());}
 private void complete(String auth)throws Exception{mvc.perform(patch("/api/v1/profile").header("Authorization",auth).contentType("application/json").content("{\"degree\":\"B.Tech Computer Science\",\"graduationYear\":2027,\"targetRole\":\"Backend Developer\",\"experienceLevel\":\"ENTRY_LEVEL\"}")).andExpect(status().isOk());mvc.perform(put("/api/v1/profile/skills").header("Authorization",auth).contentType("application/json").content("{\"skills\":[{\"displayName\":\"Java\",\"proficiencyLevel\":\"ADVANCED\"},{\"displayName\":\"Spring Boot\",\"proficiencyLevel\":\"INTERMEDIATE\"}]}")).andExpect(status().isOk());}
 private String register()throws Exception{JsonNode response=json.readTree(mvc.perform(post("/api/v1/auth/register").contentType("application/json").content("{\"fullName\":\"AI Test\",\"email\":\"career-ai@example.com\",\"password\":\"Password1\",\"confirmPassword\":\"Password1\"}")).andExpect(status().isCreated()).andReturn().getResponse().getContentAsString());return"Bearer "+response.path("accessToken").asText();}}
